import{_ as e,c as a,a2 as p,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百三十七章 一劫有多长的时间？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/137第一百三十七章 一劫有多长的时间.md","filePath":"meditation/巴利文大藏经/137第一百三十七章 一劫有多长的时间.md"}'),o={name:"meditation/巴利文大藏经/137第一百三十七章 一劫有多长的时间.md"};function r(n,t,i,s,d,c){return _(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百三十七章-一劫有多长的时间" tabindex="-1">第一百三十七章 一劫有多长的时间？ <a class="header-anchor" href="#第一百三十七章-一劫有多长的时间" aria-label="Permalink to &quot;第一百三十七章 一劫有多长的时间？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部15相应5经/山经(无始相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，有一位出家弟子来到佛陀的住所，他顶礼佛陀后，就在一旁坐下，他对佛陀说：“世尊，一劫有多长时间呢？”</p><p>佛陀说：“比丘（出家人），一劫代表很长的时间，是不太容易被估计的，劫是时间长度的计数单位，比如像几年、几百年、几千年、几十万年。由于劫代表的时间非常的长，不太好描述它具体指代的时间有多长。”</p><p>这位出家人继续问：“世尊，您能为我说一个比喻吗？用这个比喻来描述劫代表的时间长度。”</p><p>佛陀说：“比丘，这是可以的。比丘，就比如有一个长四十里、宽四十里、高四十里的大岩石，这个大岩石没有裂缝，没有孔洞，非常的坚硬牢固，有一个男子每过一百年，就用自己的衣服擦拭一次大岩石，他这样坚持每一百年就用衣服擦一次大岩石，一直到大岩石被擦的光滑透亮，被擦的小如枣核，被擦的不见了踪迹，灭尽消失了。</p><p>他每一百年就用衣服擦拭一次大岩石，他这样将大岩石擦的不见踪迹，擦的灭尽消失所用的时间就是一劫，一劫就有那么长的时间。比丘，你要明白世间的众生，他们生死轮回的时间长度不只是一劫，不只是百劫，不只是千劫，不只是十万劫。他们生死轮回的时间长度那是无数劫，是无法用时间来计量的。为什么呢？比丘，生死轮回是循环不止的，是无穷无尽的！这些不明白世间的真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们的生死轮回也是循环不止的，也是无穷无尽的，他们是无法知道他们自己生死轮回的起点在什么地方的。</p><p>比丘，你无数次的生死轮回，无数次的承受痛苦，无数次的经历不幸，无数次的忧愁、悲伤、苦闷、忧虑、绝望。无数次的死后埋入墓地。比丘，你要从世间解脱出来，要从生死轮回中解脱出来，就不要再挂念和执着世间一切的事物，就不要再执着和挂念自己一切的行为、言语、念想。这样你就不会被世间一切的事物束缚捆绑，这样你就不会被自己的行为、言语、念想束缚捆绑。这样你就能最终从生死轮回中永远的解脱出来。”</p><p>佛陀说法后，这位听法的出家弟子再次的顶礼佛陀，他随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行。</p>',10)]))}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
